---@class ActionComponent
local ActionComponent = Class("ActionComponent",ECSComponent)

function ActionComponent:__init()
    self.name = "ActionComponent"
    self._mapInfo = {}             --区域信息
    self._timeDown = nil
    self._bossTypeInfo = {}

    self._storeRemainTime = 0      --商店刷新倒计时
    self._dayRefreshTime = 0      --每日刷新时间

    self._passQuests = {}      --所有通关了的关卡

    self._allTask = {}      --任务

    self.remainCreateRewardTimes = 0        -- 创建房间的剩余奖励次数

    self.resources = { Constants.Currency.HpId }
end

function ActionComponent:__delete()
    self._mapInfo = {}             --区域信息
    self._timeDown = nil
    self._bossTypeInfo = {}

    self._storeRemainTime = 0      --商店刷新倒计时
    self._dayRefreshTime = 0      --每日刷新时间
    self._passQuests = {}      --所有通关了的关卡
    self._allTask = {}      --任务
    self.remainCreateRewardTimes = 0        -- 创建房间的剩余奖励次数

    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

