end

function ActionComponent:InitHomeData(jsonData)    
    self._mapInfo = {}
    self.remainCreateRewardTimes = checkNumber(jsonData.remainCreateRewardTimes)
    self._dayRefreshTime = checkNumber(jsonData.remainTime)

    local t = jsonData.overseaRegionMapInfo
    self._passQuests = {}  
    for k, v in pairs(t) do
        -- regionId
        -- regionLevel
        -- regionExp
        -- regionQuestInfo
        -- takeoutOrders
        -- regionalBossData = {
            --state           --0未开始 1进行中 2已完成
            --type            --歼灭战类型表
            --lastQuestId      --当前最新通关id
            --remainTime      --剩余时间  
            --progress        --当前进度 0-1  
        --}
        self._mapInfo[checkString(v.regionId)] = v
        local t1 = checkTable(v.regionQuestInfo)
        for _, _questIds in pairs(t1) do
            for _ind, _questId in pairs(checkTable(_questIds)) do
                self._passQuests[checkString(_questId)] = 1
            end
        end  
    end
    
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    ---刷新下外卖订单数据
    if jsonData.takeOutOrders and table.count(jsonData.takeOutOrders) > 0 then
        maidCoffeePlayerComponent:ResetTakeoutOrders(jsonData.takeOutOrders)
    end
    
    if isSet(jsonData,"takeOutDailyTimes") then
        maidCoffeePlayerComponent:UpdateTakeOutDailyTimes(checkTable(jsonData.takeOutDailyTimes))
    end
    
    if isSet(jsonData,"allTakeoutTimes") then
        maidCoffeePlayerComponent:UpdateTakeOutAllTimes(jsonData.allTakeoutTimes)
    end
    
    -- 歼灭战boss信息
    self._bossTypeInfo = checkTable(jsonData.allBossQuestData)
end

--入口
function ActionComponent:OverseaRegionalHomeReq(cb)
    GameUtils.Request(Interfaces.OverseaRegionalHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self:InitHomeData(jsonData)

        self:StartTimeDown()

        if cb then 
            cb()
        end
    end)
end

function ActionComponent:GetAllTask()
    return checkTable(self._allTask)
end

--升级
function ActionComponent:OverseaRegionalMapUpgradeReq(mapId, cb)
    GameUtils.Request(Interfaces.OverseaRegionalMapUpgrade, {regionId = mapId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._mapInfo[checkString(mapId)].regionLevel = checkNumber(self._mapInfo[checkString(mapId)].regionLevel) + 1
        self._mapInfo[checkString(mapId)].taskProgress = 0
        self._mapInfo[checkString(mapId)].canReceiveTask = 0

        self._allTask = checkTable(jsonData.taskList)    --任务
        if cb then 
            cb(jsonData.rewards)
        end
    end)
end

