--区域任务领取
function ActionComponent:OverseaRegionalMapTaskDrawReq(taskId, groupId, mapId, cb)
    GameUtils.Request(Interfaces.OverseaRegionalMapTaskDraw, {taskId = taskId, regionId = mapId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        
        local count = 0
        if checkNumber(taskId) == 0 then 
            for k, v in pairs(self._allTask) do
                for _, data in pairs(v) do
                    if checkNumber(data.status) == 1 then
                        data.status = 2
                        count = count + 1
                    end
                end
            end
            self._mapInfo[checkString(mapId)].canReceiveTask = 0
        else
            count = 1
            self._mapInfo[checkString(mapId)].canReceiveTask = checkNumber(self._mapInfo[checkString(mapId)].canReceiveTask) - 1
            local t = self._allTask[checkString(groupId)]
            if t then
                if t[checkString(taskId)] then
                    t[checkString(taskId)].status = 2
                end
            end
        end

        self._mapInfo[checkString(mapId)].taskProgress = checkNumber(self._mapInfo[checkString(mapId)].taskProgress) + count

        GoodsUtils.DrawRewards(jsonData.rewards, true)

        if cb then 
            cb(jsonData.rewards)
        end
    end)
end

