--歼灭战倒计时
function ActionComponent:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        for k, v in pairs(self._mapInfo) do
            if v.regionalBossData then
                if checkNumber(v.regionalBossData.state) == 1 then
                    v.regionalBossData.remainTime = checkNumber(v.regionalBossData.remainTime) - 1

                    if v.regionalBossData.remainTime == 0 then
                        v.regionalBossData.state = 2
                    end
                end
            end
        end
        self._dayRefreshTime = self._dayRefreshTime - 1
        if self._dayRefreshTime <= 0 then
            self._dayRefreshTime = 86400
        end
    end, CountDownTime, false, true)
end

function ActionComponent:GetDayRefreshTime()
    return self._dayRefreshTime
end

