--区域普通关卡信息
function ActionComponent:UpdateReginQuestInfo(questId, regionalBossData, consumeActivityResidueNum)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not questVo then
        return
    end
    if checkNumber(questVo.levelType) == Constants.RegionSecondQuestType.Equip and consumeActivityResidueNum ~= nil then
        ---如果是打的是装备关卡，活加动情况下
        --@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
        if status == 1 then
            playerComponent.playerDojo.consumeCopyActivity.residueNum = checkNumber(consumeActivityResidueNum)
        end
    end
    print('-----UpdateReginQuestInfo--', questId)
    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
    local vo = ActionUtils.GetRegionSecondaryMapVo(questVo.pointID)
    if not vo then
        return
    end

    local t = self._mapInfo[checkString(vo.regionBelong)].regionQuestInfo
    --有这个key说明是普通
    if t[checkString(vo.id)] then
        self._passQuests[checkString(questId)] = 1
        --local curQuestId = t[checkString(vo.id)]
        --if checkNumber(questId) > checkNumber(curQuestId) then
        --    t[checkString(vo.id)].questId = checkNumber(questId)
        --end
    end

    if regionalBossData then
        local isOpen1 = ActionUtils.IsOpenAnnihilation(vo.regionBelong)
        self._mapInfo[checkString(vo.regionBelong)].regionalBossData = checkTable(regionalBossData)
        local isOpen2 = ActionUtils.IsOpenAnnihilation(vo.regionBelong)
        --有歼灭战开启了
        if isOpen2 and not isOpen1 then
            CS.Engine.Lib.KCookie.Set("RegionalBossNewUnlock", vo.regionBelong)
        end
    end
end

