function ActionComponent:AddUnlockPointIds(id)
    if not self._unlockPointIds then
        self._unlockPointIds = {}
    end
    if checkNumber(id) > 0 then
        table.insert(self._unlockPointIds, checkNumber(id))
    end
end

function ActionComponent:GetUnlockPointIds()
    local t = checkTable(self._unlockPointIds)
    self._unlockPointIds = {}
    return t
end

function ActionComponent:GetRedPointIds()
    if isNull(self._allRedPointIds) then
        local str = CfUtils.GetLocalData("ActionRedpointDataTow", "")
        self._allRedPointIds = checkTable(CfUtils.Split(str, ","))
    end
    return self._allRedPointIds
end

function ActionComponent:RemoveRedPointId(id)
    if isNull(self._allRedPointIds) then
        self._allRedPointIds = {}
    end
    for i = table.count(self._allRedPointIds), 1, -1 do
        if checkNumber(id) == checkNumber(self._allRedPointIds[i]) then
            table.remove(self._allRedPointIds, i)
        end
    end
end

function ActionComponent:AddRedPointId(id)
    if isNull(self._allRedPointIds) then
        self._allRedPointIds = {}
    end
    table.insert(self._allRedPointIds, id)
end

